// Real token validation for L1 notify (Phase 2B fix)
// Token from env credential, exact match only, reject missing/wrong, never log
const headers = $input.first().json.headers || $json.headers || {};
const body = $input.first().json.body || $json.body || $json;

const expected = ($env.N8N_WEBHOOK_TOKEN || $env.N8N_CALLBACK_TOKEN || '').trim();
if (!expected) {
  throw new Error('Server misconfigured: shared token not set in n8n env');
}
const authHeader = (headers['authorization'] || '').trim();
const bearer = authHeader.toLowerCase().startsWith('bearer ') ? authHeader.slice(7).trim() : '';
const supplied = (headers['x-n8n-token'] || headers['x-callback-token'] || bearer || '').trim();
if (!supplied) {
  throw new Error('Missing authentication token - X-N8N-Token required');
}
if (supplied !== expected) {
  throw new Error('Invalid authentication token');
}

// Ensure no full_log (defense in depth)
const payloadStr = JSON.stringify(body).toLowerCase();
if (payloadStr.includes('full_log')) {
  throw new Error('Security violation: payload must not contain full_log');
}

return { json: body.payload ? body.payload : body };

// Format L1 notification (Phase 2D fix)
// Render human-readable email text from the structured payload.
// - rule/iocs are OBJECTS in the payload: never interpolate objects directly
//   (renders [object Object]) and never JSON.stringify raw structures.
// - investigation links come from alert.investigation_links (the payload's
//   allow-listed set); feedback_url is provided by triage-api.
// Summary only: no full_log, no secrets. No autonomous response.
const alert = $input.first().json;
const severity = (alert.severity || 'unknown').toUpperCase();
const score = alert.score ?? 'n/a';
const decision = alert.decision || {};
const rule = alert.rule || {};
const links = alert.investigation_links || {};
const recurrence = alert.recurrence || {};
const enrichment = alert.enrichment || {};
const triageBase = $env.TRIAGE_API_BASE_URL || 'http://triage-api:8000';

// IOC list: payload sends iocs as an array of { type, value, enrichment }.
// Group values per type (ipv4/domain/url/md5/sha1/sha256/email) for readability.
const iocList = Array.isArray(alert.iocs) ? alert.iocs : [];
const groups = {};
for (const ioc of iocList) {
  if (!ioc || !ioc.type) continue;
  const t = ioc.type;
  if (!groups[t]) groups[t] = [];
  if (ioc.value && !groups[t].includes(ioc.value)) groups[t].push(ioc.value);
}
const joinOr = (vals) => (vals && vals.length ? vals.join(', ') : 'none');
const ruleDesc = rule.description || rule.id || 'unknown';
const decisionLabel = [decision.severity, decision.action].filter(Boolean).join(' / ') || 'unknown';
const feedbackUrl = links.feedback_url
  || `${triageBase}/api/v1/alerts/${alert.alert_id}/feedback`;
const occur = recurrence.occurrences != null ? recurrence.occurrences : 1;
const enrichmentStatus = enrichment.status || 'skipped';

const subject = `[SOC][${severity}] Alert ${alert.alert_id} - ${decisionLabel}`;

const bodyText = `
SOC Alert - L1 Review
--------------------
Alert ID: ${alert.alert_id}
Severity: ${severity}
Score: ${score}
Decision: ${decisionLabel}
Rule: ${ruleDesc} (id ${rule.id || 'n/a'}, level ${rule.level != null ? rule.level : 'n/a'})
Agent: ${(alert.agent && (alert.agent.name || alert.agent.id)) || 'unknown'}
Recurrence: ${occur} occurrence(s), dedupe ${recurrence.dedupe_status || 'n/a'}

IOCs (${iocList.length} total):
- IPs:      ${joinOr(groups.ipv4)}
- Domains:  ${joinOr(groups.domain)}
- URLs:     ${joinOr(groups.url)}
- MD5:      ${joinOr(groups.md5)}
- SHA1:     ${joinOr(groups.sha1)}
- SHA256:   ${joinOr(groups.sha256)}
- Emails:   ${joinOr(groups.email)}

Enrichment: ${enrichmentStatus} (${enrichment.ioc_count || 0} indicators)

Investigation:
- Alert API: ${links.alert_api || 'n/a'}
- Runbook:   ${links.runbook || 'n/a'}
- Feedback:  ${feedbackUrl}

Note: contain_requested creates an approval-required request; no containment
action is executed. Human approval required. No autonomous response.
`;

return {
  json: {
    alert_id: alert.alert_id,
    severity: alert.severity,
    subject,
    bodyText,
    feedbackUrl,
    toEmail: ($env.SOC_L1_EMAIL || 'soc-l1@example.com'),
    _notify: {
      formatted_at: new Date().toISOString(),
    },
  },
};
